import backtrader as bt


class SMA200RegimeStrategy(bt.Strategy):
    params = (
        ('sma_period', 200),
    )

    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=self.p.sma_period)
        self.order = None

    def log(self, txt, dt=None):
        dt = dt or self.data.datetime.date(0)
        print(f'{dt.isoformat()} {txt}')

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return
        if order.status == order.Completed:
            if order.isbuy():
                self.log(
                    f'BUY EXECUTED, Price: {order.executed.price:.2f}, '
                    f'Size: {order.executed.size}, Cost: {order.executed.value:.2f}, '
                    f'Comm: {order.executed.comm:.2f}'
                )
            else:
                self.log(
                    f'SELL EXECUTED, Price: {order.executed.price:.2f}, '
                    f'Size: {order.executed.size}, Cost: {order.executed.value:.2f}, '
                    f'Comm: {order.executed.comm:.2f}'
                )
        elif order.status in [order.Canceled, order.Margin, order.Rejected]:
            self.log(f'Order {order.getstatusname()}')
        self.order = None

    def next(self):
        current_weekday = self.data.datetime.date(0).weekday()
        if current_weekday != 4:
            return

        self.log(
            f'Close: {self.data.close[0]:.2f}, SMA200: {self.sma[0]:.2f}, '
            f'Position: {self.position.size}, Portfolio Value: {self.broker.getvalue():.2f}'
        )

        if self.order:
            return

        if not self.position:
            if self.data.close[0] > self.sma[0]:
                cash = self.broker.getcash()
                size = int(cash / self.data.close[0])
                if size > 0:
                    self.log(f'BUY CREATE, Close: {self.data.close[0]:.2f}, Size: {size}')
                    self.order = self.buy(size=size)
        else:
            if self.data.close[0] < self.sma[0]:
                self.log(f'SELL CREATE, Close: {self.data.close[0]:.2f}')
                self.order = self.close()
